head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[$p > M > getIntervalKeyList]<br/>setInterval() 메소드로 등록된 모든 Interval 타이머의 키값을 배열로 반환합니다.",
    "validation" : [
        "등록된 Interval 객체들의 키 문자열 배열을 반환해야 합니다.",
        "등록된 Interval 이 없으면 빈 배열([])을 반환해야 합니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.btn_setInterval_onclick = function () {
    $p.setInterval(function () {}, {key: "interval_A", delay: 5000});
    $p.setInterval(function () {}, {key: "interval_B", delay: 5000});

    wf_body_bottom.getObj("scwin").setReturnValue("setInterval 등록 완료 (interval_A, interval_B)");
}



scwin.btn_getIntervalKeyList_onclick = function () {
    var keyList = $p.getIntervalKeyList();

    wf_body_bottom.getObj("scwin").setReturnValue("배열 길이 : " + keyList.length + ", 키 목록 : [" + keyList.join(", ") + "]");
}



scwin.btn_clearAll_onclick = function () {
    var keyList = $p.getIntervalKeyList();
    for (var i = 0; i < keyList.length; i++) {
        $p.clearInterval(keyList[i]);
    }

    var afterList = $p.getIntervalKeyList();
    wf_body_bottom.getObj("scwin").setReturnValue("전체 제거 완료, 남은 타이머 : " + afterList.length + "개");
}
